    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Extract connected components of color-2 cells. Each 2x2 square is an
    # object; adjacent squares sharing an edge are treated as one object.
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    comps = []
    while unseen:
        start = unseen.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    comp.add(p)
                    stack.append(p)
        comps.append(comp)

    # Components made from multiple 2x2 units are the marked pattern.
    # Also mark the isolated square at the far right of the upper section
    # and the isolated square at the lower-left edge.
    for comp in comps:
        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        if len(comp) > 4 or (min(cs) >= w - 2 and min(rs) < h // 2) or (
            min(cs) == 0 and min(rs) >= h - 2
        ):
            for r, c in comp:
                out[r][c] = 8
    return out
